CREATE TABLE organization(id uuid PRIMARY KEY,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('government','consortium','business')));
CREATE TABLE actor(id uuid PRIMARY KEY,issuer text NOT NULL,subject text NOT NULL,name text NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(issuer,subject));
CREATE TABLE membership(org_id uuid NOT NULL REFERENCES organization,actor_id uuid NOT NULL REFERENCES actor,role text NOT NULL,active boolean NOT NULL DEFAULT true,PRIMARY KEY(org_id,actor_id));
CREATE TABLE auth_session(org_id uuid NOT NULL REFERENCES organization,id text NOT NULL,actor_id uuid NOT NULL REFERENCES actor,csrf_digest text NOT NULL,expires_at timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false,PRIMARY KEY(org_id,id));
CREATE TABLE municipality(ibge char(7) PRIMARY KEY CHECK(ibge ~ '^[0-9]{7}$'),name text NOT NULL,uf char(2) NOT NULL,origin text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE item_version(id text NOT NULL,version int NOT NULL CHECK(version>0),name text NOT NULL,family text NOT NULL,unit text NOT NULL,step numeric(24,8) NOT NULL CHECK(step>0),example_price numeric(24,8),classification text NOT NULL DEFAULT 'synthetic',PRIMARY KEY(id,version));
CREATE TABLE source_observation(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organization,provider text NOT NULL,url text NOT NULL,consulted_at timestamptz NOT NULL DEFAULT now(),http_status int NOT NULL,sha256 char(64) NOT NULL,body text NOT NULL,metadata jsonb NOT NULL,classification text NOT NULL CHECK(classification IN ('official','synthetic')),UNIQUE(provider,url,sha256));
CREATE TABLE buyer(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organization,cnpj text,name text NOT NULL,unit_code text,municipality_ibge char(7) REFERENCES municipality,government_level text,classification text NOT NULL,external_identity text NOT NULL,UNIQUE(classification,external_identity));
CREATE TABLE procurement_fact(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organization,classification text NOT NULL CHECK(classification IN ('official','synthetic')),provider text NOT NULL,event_identity text NOT NULL,revision_hash text NOT NULL,is_current boolean NOT NULL DEFAULT true,supersedes_id uuid REFERENCES procurement_fact,source_id uuid NOT NULL REFERENCES source_observation,buyer_id uuid REFERENCES buyer,municipality_ibge char(7) REFERENCES municipality,item_id text,item_version int,description text NOT NULL,unit text,quantity numeric(24,8) CHECK(quantity>=0),unit_price numeric(24,8) CHECK(unit_price>=0),amount numeric(24,8) CHECK(amount>=0),phase text NOT NULL CHECK(phase IN ('publicado_estimado','homologado','contratado','solicitado','entregue','consumido','empenhado','liquidado','pago','estorno')),event_date date,obligation_id text NOT NULL,metadata jsonb NOT NULL,FOREIGN KEY(item_id,item_version) REFERENCES item_version,UNIQUE(provider,event_identity,revision_hash,classification));
CREATE UNIQUE INDEX fact_current ON procurement_fact(provider,event_identity,classification) WHERE is_current;
CREATE INDEX fact_query ON procurement_fact(municipality_ibge,item_id,item_version,phase) WHERE is_current;
CREATE TABLE coverage(org_id uuid NOT NULL REFERENCES organization,id uuid NOT NULL,provider text NOT NULL,scope jsonb NOT NULL,state text NOT NULL CHECK(state IN ('not_consulted','partial','complete','empty','unavailable')),pages_fetched int NOT NULL CHECK(pages_fetched>=0),expected_pages int,record_count int NOT NULL,latest_success_at timestamptz,last_error_code text,PRIMARY KEY(org_id,id));
CREATE TABLE scenario(org_id uuid NOT NULL REFERENCES organization,id uuid NOT NULL,title text NOT NULL,current_revision int NOT NULL,classification text NOT NULL CHECK(classification IN ('synthetic','internal')),created_by uuid NOT NULL REFERENCES actor,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id));
CREATE TABLE scenario_version(org_id uuid NOT NULL,scenario_id uuid NOT NULL,revision int NOT NULL CHECK(revision>0),snapshot jsonb NOT NULL,created_by uuid NOT NULL REFERENCES actor,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,scenario_id,revision),FOREIGN KEY(org_id,scenario_id) REFERENCES scenario);
ALTER TABLE scenario ADD FOREIGN KEY(org_id,id,current_revision) REFERENCES scenario_version DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE scenario_participant(org_id uuid NOT NULL,scenario_id uuid NOT NULL,revision int NOT NULL,ibge char(7) NOT NULL REFERENCES municipality,PRIMARY KEY(org_id,scenario_id,revision,ibge),FOREIGN KEY(org_id,scenario_id,revision) REFERENCES scenario_version);
CREATE TABLE scenario_item(org_id uuid NOT NULL,scenario_id uuid NOT NULL,revision int NOT NULL,item_id text NOT NULL,item_version int NOT NULL,PRIMARY KEY(org_id,scenario_id,revision,item_id,item_version),FOREIGN KEY(org_id,scenario_id,revision) REFERENCES scenario_version,FOREIGN KEY(item_id,item_version) REFERENCES item_version);
CREATE TABLE calculation(org_id uuid NOT NULL,id uuid NOT NULL,scenario_id uuid NOT NULL,revision int NOT NULL,core_sha256 text NOT NULL,summary jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,scenario_id,revision) REFERENCES scenario_version);
CREATE TABLE calculation_line(org_id uuid NOT NULL,calculation_id uuid NOT NULL,ibge char(7) NOT NULL,item_id text NOT NULL,item_version int NOT NULL,unit text NOT NULL,quantity numeric(24,8),unit_price numeric(24,8),value numeric(24,2),state text NOT NULL,memory jsonb NOT NULL,PRIMARY KEY(org_id,calculation_id,ibge,item_id,item_version),FOREIGN KEY(org_id,calculation_id) REFERENCES calculation,FOREIGN KEY(ibge) REFERENCES municipality,FOREIGN KEY(item_id,item_version) REFERENCES item_version);
CREATE TABLE private_quote(org_id uuid NOT NULL REFERENCES organization,id uuid NOT NULL,current_revision int NOT NULL,created_by uuid NOT NULL REFERENCES actor,PRIMARY KEY(org_id,id));
CREATE TABLE quote_version(org_id uuid NOT NULL,quote_id uuid NOT NULL,revision int NOT NULL,inputs jsonb NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,quote_id,revision),FOREIGN KEY(org_id,quote_id) REFERENCES private_quote);
CREATE TABLE document(org_id uuid NOT NULL REFERENCES organization,id uuid NOT NULL,filename text NOT NULL,sha256 char(64) NOT NULL,storage_key text NOT NULL,classification text NOT NULL CHECK(classification IN ('internal','business_private','synthetic')),created_by uuid NOT NULL REFERENCES actor,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),UNIQUE(org_id,sha256));
CREATE TABLE extracted_document(org_id uuid NOT NULL,document_id uuid NOT NULL,revision int NOT NULL,parser_version text NOT NULL,result jsonb NOT NULL,review_state text NOT NULL,reviewer uuid REFERENCES actor,PRIMARY KEY(org_id,document_id,revision),FOREIGN KEY(org_id,document_id) REFERENCES document);
CREATE TABLE artifact(org_id uuid NOT NULL REFERENCES organization,id uuid NOT NULL,classification text NOT NULL,storage_key text NOT NULL,filename text NOT NULL,media_type text NOT NULL,sha256 char(64) NOT NULL,scenario_id uuid,revision int,created_by uuid NOT NULL REFERENCES actor,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,scenario_id,revision) REFERENCES scenario_version);
CREATE TABLE job(org_id uuid NOT NULL REFERENCES organization,id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES actor,kind text NOT NULL,idempotency_key text NOT NULL,input_hash text NOT NULL,arguments jsonb NOT NULL,state text NOT NULL,result jsonb,error_code text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),UNIQUE(org_id,actor_id,kind,idempotency_key));
CREATE TABLE ai_session(org_id uuid NOT NULL REFERENCES organization,id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES actor,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id));
CREATE TABLE ai_turn(org_id uuid NOT NULL,id uuid NOT NULL,session_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES actor,context_revision text NOT NULL,question_digest text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,session_id) REFERENCES ai_session);
CREATE TABLE ai_cache(org_id uuid NOT NULL REFERENCES organization,key text NOT NULL,actor_id uuid NOT NULL REFERENCES actor,permission_revision text NOT NULL,result jsonb NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(org_id,key));
CREATE TABLE ai_reservation(org_id uuid NOT NULL REFERENCES organization,id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES actor,operation text NOT NULL,amount numeric(20,8) NOT NULL CHECK(amount>=0),billed numeric(20,8),state text NOT NULL CHECK(state IN ('reserved','reconciled','uncertain')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id));
CREATE TABLE audit_event(org_id uuid NOT NULL REFERENCES organization,id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES actor,action text NOT NULL,resource_id text NOT NULL,metadata jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id));
CREATE TABLE watch(org_id uuid NOT NULL REFERENCES organization,id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES actor,query jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id));

CREATE FUNCTION irps_deny_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable_evidence'; END; $$;
CREATE TRIGGER source_immutable BEFORE UPDATE OR DELETE ON source_observation FOR EACH ROW EXECUTE FUNCTION irps_deny_mutation();
CREATE TRIGGER version_immutable BEFORE UPDATE OR DELETE ON scenario_version FOR EACH ROW EXECUTE FUNCTION irps_deny_mutation();
CREATE TRIGGER quote_version_immutable BEFORE UPDATE OR DELETE ON quote_version FOR EACH ROW EXECUTE FUNCTION irps_deny_mutation();
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['membership','auth_session','coverage','scenario','scenario_version','scenario_participant','scenario_item','calculation','calculation_line','private_quote','quote_version','document','extracted_document','artifact','job','ai_session','ai_turn','ai_cache','ai_reservation','audit_event','watch'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY tenant_scope ON %I USING (org_id = nullif(current_setting(''irps.org_id'',true),'''')::uuid) WITH CHECK (org_id = nullif(current_setting(''irps.org_id'',true),'''')::uuid)',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['source_observation','buyer','procurement_fact'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY public_or_tenant ON %I FOR SELECT USING (classification = ''official'' OR org_id = nullif(current_setting(''irps.org_id'',true),'''')::uuid)',t);
  EXECUTE format('CREATE POLICY tenant_insert ON %I FOR INSERT WITH CHECK (org_id = nullif(current_setting(''irps.org_id'',true),'''')::uuid)',t);
  EXECUTE format('CREATE POLICY tenant_update ON %I FOR UPDATE USING (org_id = nullif(current_setting(''irps.org_id'',true),'''')::uuid) WITH CHECK (org_id = nullif(current_setting(''irps.org_id'',true),'''')::uuid)',t);
 END LOOP;
END $$;
GRANT USAGE ON SCHEMA public TO irps_app;
GRANT SELECT ON organization,actor,municipality,item_version TO irps_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON membership,auth_session,coverage,scenario,scenario_version,scenario_participant,scenario_item,calculation,calculation_line,private_quote,quote_version,document,extracted_document,artifact,job,ai_session,ai_turn,ai_cache,ai_reservation,audit_event,watch TO irps_app;
GRANT SELECT,INSERT,UPDATE ON source_observation,buyer,procurement_fact TO irps_app;
GRANT INSERT,UPDATE ON municipality TO irps_app;
REVOKE UPDATE,DELETE ON source_observation,scenario_version,quote_version FROM irps_app;
